-- GUS-242 step 1f — vocabularies.
--
-- Families, techniques and contexts, grown to the sizes the
-- GUS-242 plan set, with a parent_id hierarchy on the families.
--
-- Generated by scripts/build_vocab_1f.py + scripts/emit_vocab_1f_sql.py
-- from a single source of truth, so the row set and the assertions
-- cannot drift apart.
--
-- Run inside a transaction with the count assertions FIRST (RULES.md §3).
--
-- Usage:
--   psql -v ON_ERROR_STOP=1 -d <db> -f packages/db/drizzle/0018_gus242_vocab_1f.sql
--
-- ROLLBACK
--   DELETE FROM dish_families     WHERE slug IN (<the 168 slugs>);
--   DELETE FROM dish_techniques   WHERE slug IN (<the 63 slugs>);
--   DELETE FROM dish_contexts     WHERE slug IN (<the 26 slugs>);
--   (restore the 28 families' parent_id to NULL)

\set ON_ERROR_STOP on

BEGIN;

-- =====================================================================
-- ASSERTIONS (before any write).
-- =====================================================================

-- The families grow from 28 to 196.
DO $$
DECLARE n int;
BEGIN
  SELECT count(*) INTO n FROM dish_families WHERE slug <> '';
  IF n <> 28 THEN
    RAISE EXCEPTION 'A1 failed: expected 28 existing families, found %', n;
  END IF;

  SELECT count(*) INTO n FROM dish_techniques WHERE slug <> '';
  IF n <> 26 THEN
    RAISE EXCEPTION 'A2 failed: expected 26 existing techniques, found %', n;
  END IF;

  SELECT count(*) INTO n FROM dish_contexts WHERE slug <> '';
  IF n <> 5 THEN
    RAISE EXCEPTION 'A3 failed: expected 5 existing contexts, found %', n;
  END IF;

  -- None of the new slugs may already exist.
  SELECT count(*) INTO n FROM dish_families WHERE slug IN (
    'beverage', 'alcoholic-drink', 'spirit', 'fermented-drink', 'confection', 'frozen-dessert', 'indian-sweet', 'preserved-vegetable', 'fermented-vegetable', 'fermented-soy', 'cured-meat', 'thali', 'rijsttafel', 'meze', 'banchan', 'nasi-campur', 'flatbread', 'baked-bread', 'pita', 'naan', 'tortilla', 'rice-balls', 'risotto', 'biryani', 'pilaf', 'pulao', 'congee', 'sticky-rice', 'rice-noodle', 'noodle-dish', 'ramen', 'pho', 'laksa', 'dough', 'pie', 'tart', 'crepe', 'waffle', 'hot-pot', 'fondue', 'broth', 'bouillon', 'bisque', 'chowder', 'minestrone', 'chili', 'shakshuka', 'potjiekos', 'budae-jjigae', 'polenta', 'couscous', 'muesli', 'granola', 'roasted-vegetable', 'grilled-vegetable', 'fried-vegetable', 'pickled-vegetable', 'leafy-green', 'mushroom-dish', 'legume-dish', 'tofu-dish', 'grilled-meat', 'roast-meat', 'braised-meat', 'fried-chicken', 'roast-chicken', 'braised-poultry', 'dried-meat', 'sausage', 'meatball', 'bacon', 'ham', 'prosciutto', 'grilled-fish', 'fried-fish', 'steamed-fish', 'raw-fish', 'cured-fish', 'shellfish', 'fish-soup', 'omelette', 'egg-tart', 'custard', 'burger', 'hot-dog', 'burrito', 'wrap', 'quesadilla', 'panini', 'open-faced-sandwich', 'tempura', 'falafel', 'samosa', 'croquette', 'chips', 'french-fries', 'tempura-fries', 'chips-fry', 'shashlik', 'satay', 'skewer', 'barbecue', 'chinese-hot-pot', 'pickle', 'cake', 'cookie', 'biscuit', 'sweet-tart', 'sweet-pie', 'pudding', 'sweet-custard', 'ice-cream', 'sorbet', 'gelato', 'chocolate', 'candy', 'caramel', 'meringue', 'souffle', 'crumble', 'trifle', 'cheesecake', 'sweet-pudding', 'halwa', 'laddu', 'barfi', 'jalebi', 'kulfi', 'mochi', 'matcha-dessert', 'crepe-cake', 'panna-cotta', 'tiramisu', 'baklava', 'cannoli', 'cendol', 'sweet-crepe', 'tea', 'coffee', 'juice', 'smoothie', 'shake', 'cocktail', 'wine', 'beer', 'cider', 'kombucha', 'lassi', 'ayran', 'kefir', 'horchata', 'aguas-frescas', 'bubbletea', 'lemonade', 'drink', 'sake', 'soju', 'baijiu', 'tequila', 'mezcal', 'rum', 'brandy', 'kimchi', 'sa