    RAISE EXCEPTION 'A4 failed: % of the new family slugs already exist', n;
  END IF;

  SELECT count(*) INTO n FROM dish_techniques WHERE slug IN (
    'broiling', 'barbecue', 'shallow-frying', 'stirring', 'whipping', 'proofing', 'laminating', 'rolling', 'grating', 'mincing', 'slicing', 'dicing', 'julienning', 'drying', 'dehydrating', 'candying', 'caramelizing', 'blending', 'pureeing', 'straining', 'reducing', 'deglazing', 'marinating', 'toasting', 'charring', 'freezing', 'chilling', 'tempering-meat', 'resting', 'griddle', 'wok', 'clay-oven', 'sun-drying', 'salt-curing', 'oil-curing', 'sugaring', 'skimming', 'pressing', 'wringing'
  );
  IF n <> 0 THEN
    RAISE EXCEPTION 'A5 failed: % of the new technique slugs already exist', n;
  END IF;

  SELECT count(*) INTO n FROM dish_contexts WHERE slug IN (
    'tableside', 'street-vendor', 'home-cooking', 'banquet', 'buffet', 'picnic', 'camping', 'school-meal', 'hospitality', 'festive', 'fasting', 'breakfast', 'lunch', 'dinner', 'supper', 'snack', 'dessert-course', 'appetizer', 'condiment-course', 'preserved', 'emergency-ration', 'travel-food', 'funeral', 'temple-offering', 'military', 'workplace'
  );
  IF n <> 0 THEN
    RAISE EXCEPTION 'A6 failed: % of the new context slugs already exist', n;
  END IF;

  -- The five meal-set families MUST be present: they are the only
  -- composed_of family values (spec §2).
  SELECT count(*) INTO n FROM (VALUES
    ('thali'),('rijsttafel'),('meze'),('banchan'),('nasi-campur')
  ) AS m(slug) WHERE m.slug IN (
    'beverage', 'alcoholic-drink', 'spirit', 'fermented-drink', 'confection', 'frozen-dessert', 'indian-sweet', 'preserved-vegetable', 'fermented-vegetable', 'fermented-soy', 'cured-meat', 'thali', 'rijsttafel', 'meze', 'banchan', 'nasi-campur', 'flatbread', 'baked-bread', 'pita', 'naan', 'tortilla', 'rice-balls', 'risotto', 'biryani', 'pilaf', 'pulao', 'congee', 'sticky-rice', 'rice-noodle', 'noodle-dish', 'ramen', 'pho', 'laksa', 'dough', 'pie', 'tart', 'crepe', 'waffle', 'hot-pot', 'fondue', 'broth', 'bouillon', 'bisque', 'chowder', 'minestrone', 'chili', 'shakshuka', 'potjiekos', 'budae-jjigae', 'polenta', 'couscous', 'muesli', 'granola', 'roasted-vegetable', 'grilled-vegetable', 'fried-vegetable', 'pickled-vegetable', 'leafy-green', 'mushroom-dish', 'legume-dish', 'tofu-dish', 'grilled-meat', 'roast-meat', 'braised-meat', 'fried-chicken', 'roast-chicken', 'braised-poultry', 'dried-meat', 'sausage', 'meatball', 'bacon', 'ham', 'prosciutto', 'grilled-fish', 'fried-fish', 'steamed-fish', 'raw-fish', 'cured-fish', 'shellfish', 'fish-soup', 'omelette', 'egg-tart', 'custard', 'burger', 'hot-dog', 'burrito', 'wrap', 'quesadilla', 'panini', 'open-faced-sandwich', 'tempura', 'falafel', 'samosa', 'croquette', 'chips', 'french-fries', 'tempura-fries', 'chips-fry', 'shashlik', 'satay', 'skewer', 'barbecue', 'chinese-hot-pot', 'pickle', 'cake', 'cookie', 'biscuit', 'sweet-tart', 'sweet-pie', 'pudding', 'sweet-custard', 'ice-cream', 'sorbet', 'gelato', 'chocolate', 'candy', 'caramel', 'meringue', 'souffle', 'crumble', 'trifle', 'cheesecake', 'sweet-pudding', 'halwa', 'laddu', 'barfi', 'jalebi', 'kulfi', 'mochi', 'matcha-dessert', 'crepe-cake', 'panna-cotta', 'tiramisu', 'baklava', 'cannoli', 'cendol', 'sweet-crepe', 'tea', 'coffee', 'juice', 'smoothie', 'shake', 'cocktail', 'wine', 'beer', 'cider', 'kombucha', 'lassi', 'ayran', 'kefir', 'horchata', 'aguas-frescas', 'bubbletea', 'lemonade', 'drink', 'sake', 'soju', 'baijiu', 'tequila', 'mezcal', 'rum', 'brandy', 'kimchi', 'sauerkraut', 'miso', 'tempeh', 'natto', 'marmite'
  );
  IF n <> 5 THEN
    RAISE EXCEPTION 'A7 failed: expected all 5 meal-set families in the batch, found %', n;
  END IF;

  -- The stress-set context value MUST be present.
  SELECT count(*) INTO n FROM (VALUES ('tableside')) AS m(slug)
   WHERE m.slug IN ('tableside', 'street-vendor', 'home-cooking', 'banquet', 'buffet', 'picnic', 'camping', 'school-meal', 'hospitality', 'festive', 'fasting', 'breakfast', 'lunch', 'dinner', 'supper', 'snack', 'dessert-course', 'appetizer', 'condiment-course', 'preserved', 'emergency-ration', 'travel-food', 'funeral', 'temple-offering', 'military', 'workplace');
  IF n <> 1 THEN
    RAISE EXCEPTION 'A8 failed: the tableside context is missing from the batch';
  END IF;
END $$;

