VALUES ('workplace', 'Workplace', 'Eaten at work, as a packed lunch.');

-- =====================================================================
-- POST-ASSERTIONS.
-- =====================================================================

DO $$
DECLARE n int;
BEGIN
  SELECT count(*) INTO n FROM dish_families;
  IF n <> 196 THEN
    RAISE EXCEPTION 'P1 failed: expected 196 families, found %', n;
  END IF;

  SELECT count(*) INTO n FROM dish_techniques;
  IF n <> 65 THEN
    RAISE EXCEPTION 'P2 failed: expected 65 techniques, found %', n;
  END IF;

  SELECT count(*) INTO n FROM dish_contexts;
  IF n <> 31 THEN
    RAISE EXCEPTION 'P3 failed: expected 31 contexts, found %', n;
  END IF;

  -- Every family's parent_id must resolve, and no family may be
  -- its own parent.
  SELECT count(*) INTO n FROM dish_families c
    LEFT JOIN dish_families p ON p.id = c.parent_id
   WHERE c.parent_id IS NOT NULL AND p.id IS NULL;
  IF n <> 0 THEN
    RAISE EXCEPTION 'P4 failed: % families have an unresolved parent', n;
  END IF;

  SELECT count(*) INTO n FROM dish_families WHERE parent_id = id;
  IF n <> 0 THEN
    RAISE EXCEPTION 'P5 failed: % families are their own parent', n;
  END IF;

  -- The hierarchy must be acyclic. Walk up from every family with a
  -- depth limit; if the walk ever lands back on the family it
  -- started from, that family is in a cycle.
  SELECT count(*) INTO n FROM (
    WITH RECURSIVE walk AS (
      SELECT id AS start, id AS node, parent_id, 1 AS lvl
        FROM dish_families WHERE parent_id IS NOT NULL
      UNION ALL
      SELECT w.start, p.id, p.parent_id, w.lvl + 1
        FROM walk w
        JOIN dish_families p ON p.id = w.parent_id
       WHERE w.lvl < 50 AND p.id IS NOT NULL
    )
    SELECT DISTINCT start FROM walk WHERE node = start AND lvl > 1
  ) cycles;
  IF n <> 0 THEN
    RAISE EXCEPTION 'P6 failed: the family hierarchy has % cycles', n;
  END IF;

  -- The 28 pre-existing families must still be present and unmodified.
  SELECT count(*) INTO n FROM dish_families
   WHERE slug IN ('bread', 'breaded-cutlet', 'casserole', 'curry', 'dessert', 'dumpling', 'egg-dish', 'fermented-dish', 'filled-pastry', 'fried-rice', 'fritter', 'kebab', 'moussaka', 'noodle-soup', 'pancake', 'pasta', 'porridge', 'rice-dish', 'salad', 'sandwich', 'sauce', 'side-dish', 'soup', 'stew', 'stiff-porridge', 'street-snack', 'stuffed-vegetable', 'taco');
  IF n <> 28 THEN
    RAISE EXCEPTION 'P7 failed: expected all 28 pre-existing families, found %', n;
  END IF;

  -- They must have kept their NULL parent_id: 1f hangs the new
  -- values UNDER them, it does not re-parent them.
  SELECT count(*) INTO n FROM dish_families
   WHERE slug IN ('bread', 'breaded-cutlet', 'casserole', 'curry', 'dessert', 'dumpling', 'egg-dish', 'fermented-dish', 'filled-pastry', 'fried-rice', 'fritter', 'kebab', 'moussaka', 'noodle-soup', 'pancake', 'pasta', 'porridge', 'rice-dish', 'salad', 'sandwich', 'sauce', 'side-dish', 'soup', 'stew', 'stiff-porridge', 'street-snack', 'stuffed-vegetable', 'taco')
     AND parent_id IS NOT NULL;
  IF n <> 0 THEN
    RAISE EXCEPTION 'P7b failed: % pre-existing families were re-parented', n;
  END IF;

  -- Every NEW value must have a name and a description. The 28
  -- pre-existing families are excluded: several of them legitimately
  -- have no description yet, and filling those in is separate work.
  SELECT count(*) INTO n FROM dish_families
   WHERE slug NOT IN ('bread', 'breaded-cutlet', 'casserole', 'curry', 'dessert', 'dumpling', 'egg-dish', 'fermented-dish', 'filled-pastry', 'fried-rice', 'fritter', 'kebab', 'moussaka', 'noodle-soup', 'pancake', 'pasta', 'porridge', 'rice-dish', 'salad', 'sandwich', 'sauce', 'side-dish', 'soup', 'stew', 'stiff-porridge', 'street-snack', 'stuffed-vegetable', 'taco')
     AND (name IS NULL OR btrim(name) = ''
          OR description IS NULL OR btrim(description) = '');
  IF n <> 0 THEN
    RAISE EXCEPTION 'P8 failed: % new families have a missing name or description', n;
  END IF;
END $$;

COMMIT;
